// Synchronous FIFO, single clock, first-word fall-through.
// Interface: interface_spec.md; implementation plan: microarchitecture.md.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer AW     = $clog2(DEPTH);
    localparam integer CW     = $clog2(DEPTH + 1);
    localparam integer LAST_I = DEPTH - 1;
    localparam integer ONE_I  = 1;

    localparam [AW-1:0] LAST     = LAST_I[AW-1:0];
    localparam [AW-1:0] PTR_ZERO = {AW{1'b0}};
    localparam [AW-1:0] PTR_ONE  = ONE_I[AW-1:0];
    localparam [CW-1:0] CNT_ZERO = {CW{1'b0}};
    localparam [CW-1:0] CNT_ONE  = ONE_I[CW-1:0];
    localparam [CW-1:0] DEPTH_C  = DEPTH[CW-1:0];

    // Storage: datapath, not reset, written only outside reset.
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    reg [AW-1:0] wr_ptr;
    reg [AW-1:0] rd_ptr;
    reg [CW-1:0] count_q;

    reg [AW-1:0] wr_ptr_nxt;
    reg [AW-1:0] rd_ptr_nxt;
    reg [CW-1:0] count_nxt;

    wire wr_acc;
    wire rd_acc;

    assign full    = (count_q == DEPTH_C);
    assign empty   = (count_q == CNT_ZERO);
    assign count   = count_q;
    assign rd_data = mem[rd_ptr];

    // The flags gate the requests: overflow and underflow policy.
    assign wr_acc = wr_en & ~full;
    assign rd_acc = rd_en & ~empty;

    always @(*) begin
        wr_ptr_nxt = wr_ptr;
        if (wr_acc) begin
            if (wr_ptr == LAST) begin
                wr_ptr_nxt = PTR_ZERO;
            end else begin
                wr_ptr_nxt = wr_ptr + PTR_ONE;
            end
        end
    end

    always @(*) begin
        rd_ptr_nxt = rd_ptr;
        if (rd_acc) begin
            if (rd_ptr == LAST) begin
                rd_ptr_nxt = PTR_ZERO;
            end else begin
                rd_ptr_nxt = rd_ptr + PTR_ONE;
            end
        end
    end

    always @(*) begin
        count_nxt = count_q;
        if (wr_acc && !rd_acc) begin
            count_nxt = count_q + CNT_ONE;
        end else if (!wr_acc && rd_acc) begin
            count_nxt = count_q - CNT_ONE;
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= PTR_ZERO;
            rd_ptr  <= PTR_ZERO;
            count_q <= CNT_ZERO;
        end else begin
            wr_ptr  <= wr_ptr_nxt;
            rd_ptr  <= rd_ptr_nxt;
            count_q <= count_nxt;
        end
    end

    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) begin
            assume(!rst_n);
        end
    end

    localparam integer FPAD = CW + 1 - AW;

    wire [CW:0] f_depth  = {1'b0, DEPTH_C};
    wire [CW:0] f_rd_x   = {{FPAD{1'b0}}, rd_ptr};
    wire [CW:0] f_sum    = f_rd_x + {1'b0, count_q};
    wire [CW:0] f_wrap   = (f_sum >= f_depth) ? (f_sum - f_depth) : f_sum;
    wire [AW-1:0] f_wr_exp = f_wrap[AW-1:0];

    (* anyconst *) reg [AW-1:0] f_addr;
    reg             f_valid;
    reg [WIDTH-1:0] f_data;

    always @(*) begin
        assume(f_addr <= LAST);
    end

    wire [CW:0] f_addr_x = {{FPAD{1'b0}}, f_addr};
    wire [CW:0] f_off    = (f_addr_x >= f_rd_x) ? (f_addr_x - f_rd_x)
                                                : (f_addr_x + f_depth - f_rd_x);
    wire        f_in_use = (f_off < {1'b0, count_q});

    always @(posedge clk) begin
        if (!rst_n) begin
            f_valid <= 1'b0;
        end else if (wr_acc && (wr_ptr == f_addr)) begin
            f_valid <= 1'b1;
            f_data  <= wr_data;
        end else if (rd_acc && (rd_ptr == f_addr)) begin
            f_valid <= 1'b0;
        end
    end

    always @(*) begin
        if (f_past_valid) begin
            assert(count_q <= DEPTH_C);
            assert(wr_ptr <= LAST);
            assert(rd_ptr <= LAST);
            assert(full == (count_q == DEPTH_C));
            assert(empty == (count_q == CNT_ZERO));
            assert(!(full && empty));
            assert(wr_ptr == f_wr_exp);
            assert(f_valid == f_in_use);
            if (f_valid) begin
                assert(mem[f_addr] == f_data);
            end
            if (f_valid && (rd_ptr == f_addr)) begin
                assert(rd_data == f_data);
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(count_q == CNT_ZERO);
                assert(empty);
                assert(!full);
                assert(wr_ptr == PTR_ZERO);
                assert(rd_ptr == PTR_ZERO);
            end else begin
                if ($past(wr_acc) && !$past(rd_acc)) begin
                    assert(count_q == $past(count_q) + CNT_ONE);
                end
                if (!$past(wr_acc) && $past(rd_acc)) begin
                    assert(count_q == $past(count_q) - CNT_ONE);
                end
                if ($past(wr_acc) == $past(rd_acc)) begin
                    assert(count_q == $past(count_q));
                end
                if ($past(wr_en) && $past(full)) begin
                    assert(wr_ptr == $past(wr_ptr));
                end
                if ($past(rd_en) && $past(empty)) begin
                    assert(rd_ptr == $past(rd_ptr));
                end
                if ($past(wr_en) && $past(full) && !$past(rd_en)) begin
                    assert(count_q == $past(count_q));
                end
                if ($past(rd_en) && $past(empty) && !$past(wr_en)) begin
                    assert(count_q == $past(count_q));
                end
            end
        end
    end

    reg f_was_full;
    always @(posedge clk) begin
        if (!rst_n) begin
            f_was_full <= 1'b0;
        end else if (full) begin
            f_was_full <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(full);
            cover(f_was_full && empty);
            cover(f_valid && rd_acc && (rd_ptr == f_addr));
            cover(wr_acc && rd_acc);
        end
    end
`endif

endmodule

`default_nettype wire
