// Self-checking testbench for sync_fifo.
// Two DUTs on shared stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12.
// Each has a reference-queue checker comparing full, empty, count and
// rd_data on every falling edge, plus coverage goals from interface_spec 7.

module fifo_checker #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8,
    parameter integer ID    = 0
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire                       rd_en,
    input  wire [WIDTH-1:0]           wr_data,
    input  wire                       dut_full,
    input  wire                       dut_empty,
    input  wire [$clog2(DEPTH+1)-1:0] dut_count,
    input  wire [WIDTH-1:0]           dut_rd_data,
    input  wire                       final_chk,
    output reg  [31:0]                passed,
    output reg  [31:0]                failed
);

    localparam integer AW = $clog2(DEPTH);
    localparam integer CW = $clog2(DEPTH + 1);

    reg [WIDTH-1:0] q [0:DEPTH-1];
    integer head;
    integer cnt;
    integer tail;
    reg     started;
    reg     wa;
    reg     ra;
    reg     exp_full;
    reg     exp_empty;
    reg     cov_done;

    integer cv_full;
    integer cv_wfull;
    integer cv_drain;
    integer cv_rempty;
    integer cv_wr_e;
    integer cv_wr_f;
    integer cv_wr_m;
    integer cv_wrap_w;
    integer cv_wrap_r;
    integer cv_rst;

    initial begin
        passed    = 32'd0;
        failed    = 32'd0;
        head      = 0;
        cnt       = 0;
        tail      = 0;
        started   = 1'b0;
        wa        = 1'b0;
        ra        = 1'b0;
        exp_full  = 1'b0;
        exp_empty = 1'b1;
        cov_done  = 1'b0;
        cv_full   = 0;
        cv_wfull  = 0;
        cv_drain  = 0;
        cv_rempty = 0;
        cv_wr_e   = 0;
        cv_wr_f   = 0;
        cv_wr_m   = 0;
        cv_wrap_w = 0;
        cv_wrap_r = 0;
        cv_rst    = 0;
    end

    // Reference model: updated on the same edge the DUT samples.
    always @(posedge clk) begin
        if (!rst_n) begin
            if (started && (cnt > 0)) cv_rst = cv_rst + 1;
            head    = 0;
            cnt     = 0;
            started = 1'b1;
        end else if (started) begin
            wa = wr_en && (cnt != DEPTH);
            ra = rd_en && (cnt != 0);
            if (wr_en && (cnt == DEPTH)) cv_wfull = cv_wfull + 1;
            if (rd_en && (cnt == 0)) cv_rempty = cv_rempty + 1;
            if (wr_en && rd_en) begin
                if (cnt == 0) cv_wr_e = cv_wr_e + 1;
                else if (cnt == DEPTH) cv_wr_f = cv_wr_f + 1;
                else cv_wr_m = cv_wr_m + 1;
            end
            if (wa) begin
                tail = head + cnt;
                if (tail >= DEPTH) tail = tail - DEPTH;
                q[tail[AW-1:0]] = wr_data;
                if (tail == DEPTH - 1) cv_wrap_w = cv_wrap_w + 1;
            end
            if (ra) begin
                if (head == DEPTH - 1) begin
                    head = 0;
                    cv_wrap_r = cv_wrap_r + 1;
                end else begin
                    head = head + 1;
                end
            end
            if (wa && !ra) cnt = cnt + 1;
            else if (ra && !wa) cnt = cnt - 1;
            if (cnt == DEPTH) cv_full = cv_full + 1;
            if (ra && (cnt == 0)) cv_drain = cv_drain + 1;
        end
    end

    task do_check;
        input   ok;
        input integer what;
        begin
            if (ok) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("fifo_checker %0d (DEPTH %0d): check %0d failed at %0t: full=%b empty=%b count=%0d rd_data=%h; model count=%0d",
                       ID, DEPTH, what, $time, dut_full, dut_empty, dut_count, dut_rd_data, cnt);
            end
        end
    endtask

    task cov_goal;
        input integer val;
        input integer what;
        begin
            if (val > 0) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("fifo_checker %0d (DEPTH %0d): coverage goal %0d never reached", ID, DEPTH, what);
            end
        end
    endtask

    // Outputs depend only on registers, so checking at the falling edge is race-free.
    always @(negedge clk) begin
        if (started) begin
            exp_full  = (cnt == DEPTH);
            exp_empty = (cnt == 0);
            do_check(dut_full === exp_full, 1);
            do_check(dut_empty === exp_empty, 2);
            do_check(dut_count === cnt[CW-1:0], 3);
            if (!exp_empty) begin
                do_check(dut_rd_data === q[head[AW-1:0]], 4);
            end
            if (final_chk && !cov_done) begin
                cov_done = 1'b1;
                cov_goal(cv_full,   11); // filled to full
                cov_goal(cv_wfull,  12); // write while full
                cov_goal(cv_drain,  13); // drained to empty
                cov_goal(cv_rempty, 14); // read while empty
                cov_goal(cv_wr_e,   15); // write and read together when empty
                cov_goal(cv_wr_f,   16); // write and read together when full
                cov_goal(cv_wr_m,   17); // write and read together in between
                cov_goal(cv_wrap_w, 18); // write pointer wrap
                cov_goal(cv_wrap_r, 19); // read pointer wrap
                cov_goal(cv_rst,    20); // reset during traffic
            end
        end
    end

endmodule

module sync_fifo_tb;

    reg         clk;
    reg         rst_n;
    reg         wr_en;
    reg         rd_en;
    reg  [11:0] wr_data;
    reg         final_chk;

    wire        full8;
    wire        empty8;
    wire [7:0]  rd8;
    wire [3:0]  cnt8;
    wire        full5;
    wire        empty5;
    wire [11:0] rd5;
    wire [2:0]  cnt5;
    wire [31:0] pass8;
    wire [31:0] fail8;
    wire [31:0] pass5;
    wire [31:0] fail5;

    integer seed;
    integer rnd;
    integer i;
    integer mode;
    integer total_p;
    integer total_f;
    reg     w;
    reg     r;
    reg [8*64-1:0] nonce;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) u_fifo8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[7:0]),
        .full    (full8),
        .rd_en   (rd_en),
        .rd_data (rd8),
        .empty   (empty8),
        .count   (cnt8)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) u_fifo5 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full5),
        .rd_en   (rd_en),
        .rd_data (rd5),
        .empty   (empty5),
        .count   (cnt5)
    );

    fifo_checker #(.DEPTH(8), .WIDTH(8), .ID(0)) u_chk8 (
        .clk         (clk),
        .rst_n       (rst_n),
        .wr_en       (wr_en),
        .rd_en       (rd_en),
        .wr_data     (wr_data[7:0]),
        .dut_full    (full8),
        .dut_empty   (empty8),
        .dut_count   (cnt8),
        .dut_rd_data (rd8),
        .final_chk   (final_chk),
        .passed      (pass8),
        .failed      (fail8)
    );

    fifo_checker #(.DEPTH(5), .WIDTH(12), .ID(1)) u_chk5 (
        .clk         (clk),
        .rst_n       (rst_n),
        .wr_en       (wr_en),
        .rd_en       (rd_en),
        .wr_data     (wr_data),
        .dut_full    (full5),
        .dut_empty   (empty5),
        .dut_count   (cnt5),
        .dut_rd_data (rd5),
        .final_chk   (final_chk),
        .passed      (pass5),
        .failed      (fail5)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Drive inputs just after a rising edge, then wait for the next one.
    task tick;
        input w_i;
        input r_i;
        begin
            wr_en   = w_i;
            rd_en   = r_i;
            rnd     = $random(seed);
            wr_data = rnd[11:0];
            @(posedge clk);
            #1;
        end
    endtask

    task random_phase;
        input integer n;
        begin
            for (i = 0; i < n; i = i + 1) begin
                rnd  = $random(seed);
                mode = (i / 250) % 4;
                case (mode)
                    0:       begin w = (rnd[3:0] < 4'd12); r = (rnd[7:4] < 4'd5);  end
                    1:       begin w = (rnd[3:0] < 4'd5);  r = (rnd[7:4] < 4'd12); end
                    2:       begin w = rnd[8];             r = rnd[9];             end
                    default: begin w = (rnd[3:0] != 4'd0); r = (rnd[7:4] != 4'd0); end
                endcase
                tick(w, r);
            end
        end
    endtask

    initial begin
        seed      = 32'h5eed_f1f0;
        final_chk = 1'b0;
        rst_n     = 1'b0;
        wr_en     = 1'b0;
        rd_en     = 1'b0;
        wr_data   = 12'h000;

        // Reset, with requests asserted (they must be ignored).
        repeat (3) tick(1'b1, 1'b1);
        rst_n = 1'b1;

        // Read while empty.
        repeat (2) tick(1'b0, 1'b1);
        // Write and read together when empty: only the write is accepted.
        tick(1'b1, 1'b1);
        // Fill to full and keep writing (write while full).
        repeat (10) tick(1'b1, 1'b0);
        // Write and read together when full, then in between.
        repeat (2) tick(1'b1, 1'b1);
        // Drain to empty and keep reading (read while empty).
        repeat (12) tick(1'b0, 1'b1);
        // Partly fill, then stream in between (pointer wrap-around).
        repeat (3) tick(1'b1, 1'b0);
        repeat (12) tick(1'b1, 1'b1);

        // Random traffic with stalls on both sides.
        random_phase(3000);

        // Reset during traffic.
        repeat (4) tick(1'b1, 1'b0);
        rst_n = 1'b0;
        repeat (2) tick(1'b1, 1'b1);
        rst_n = 1'b1;
        random_phase(500);

        // Drain and finish.
        repeat (10) tick(1'b0, 1'b1);
        final_chk = 1'b1;
        repeat (2) tick(1'b0, 1'b0);

        total_p = pass8 + pass5;
        total_f = fail8 + fail5;
        nonce = {64{8'h00}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {64{8'h00}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_p, total_f);
        $finish;
    end

endmodule
